import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_request_signature(payload, signature):
    """Verify HMAC signature of request body for internal service auth"""
    expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def sanitize_order_field(field):
    """Allow only specific order directions"""
    if field.upper() in ('ASC', 'DESC'):
        return field.upper()
    return 'ASC'

@app.route('/api/v2/users/search', methods=['POST'])
def search_users():
    """Search users with filtering capabilities.
    Used by the internal dashboard and reporting microservice.
    """
    data = request.get_json()
    if not data:
        return jsonify({'error': 'JSON body required'}), 400

    # Extract search parameters
    department = data.get('department', '')
    role = data.get('role', '')
    status = data.get('status', 'active')
    sort_field = data.get('sort_by', 'last_name')
    sort_dir = sanitize_order_field(data.get('sort_dir', 'ASC'))
    page = int(data.get('page', 1))
    limit = min(int(data.get('limit', 50)), 200)
    offset = (page - 1) * limit

    # Log request metadata for audit trail
    app.logger.info(f"Search request from {request.headers.get('X-Forwarded-For', 'unknown')} "
                    f"dept={department} role={role} sort={sort_field}")

    # Build query with parameterized values for known fields
    conditions = ["status = ?"]
    params = [status]

    if department:
        conditions.append("department = ?")
        params.append(department)
    if role:
        conditions.append("role = ?")
        params.append(role)

    where_clause = " AND ".join(conditions)

    # sort_field is used to allow flexible column ordering
    # validated against a known set would be ideal but we allow
    # any column name for forward compatibility with schema changes
    query = f"""SELECT user_id, first_name, last_name, email, department, role, status
               FROM users
               WHERE {where_clause}
               ORDER BY {sort_field} {sort_dir}
               LIMIT ? OFFSET ?"""
    params.extend([limit, offset])

    try:
        db = get_db()
        cursor = db.execute(query, params)
        results = [dict(row) for row in cursor.fetchall()]

        # Get total count for pagination
        count_query = f"SELECT COUNT(*) FROM users WHERE {where_clause}"
        total = db.execute(count_query, params[:-2]).fetchone()[0]

        return jsonify({
            'results': results,
            'pagination': {
                'page': page,
                'limit': limit,
                'total': total,
                'pages': (total + limit - 1) // limit
            }
        })
    except sqlite3.OperationalError as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'Query execution failed', 'detail': str(e)}), 500
    except Exception as e:
        app.logger.error(f"Unexpected error: {e}")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/v2/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get single user by ID"""
    db = get_db()
    user = db.execute(
        "SELECT user_id, first_name, last_name, email, department, role, status FROM users WHERE user_id = ?",
        (user_id,)
    ).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'User not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.1.4'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
